import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  counters: defineTable({
    runId: v.string(),
    count: v.number(),
  }).index("by_runId", ["runId"]),
});

import { query, mutation } from "./_generated/server";
import { v } from "convex/values";

export const getCounter = query({
  args: { runId: v.string() },
  handler: async (ctx, args) => {
    const counter = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", args.runId))
      .first();
    return counter ? counter.count : 0;
  },
});

export const incrementCounter = mutation({
  args: { runId: v.string() },
  handler: async (ctx, args) => {
    const counter = await ctx.db
      .query("counters")
      .withIndex("by_runId", (q) => q.eq("runId", args.runId))
      .first();

    if (counter) {
      await ctx.db.patch(counter._id, { count: counter.count + 1 });
    } else {
      await ctx.db.insert("counters", { runId: args.runId, count: 1 });
    }
  },
});

import { useQuery, useMutation } from "convex/react";
import { api } from "../convex/_generated/api";
import './App.css'

function App() {
  const runId = import.meta.env.VITE_RUN_ID || "default-run-id";
  const count = useQuery(api.counter.getCounter, { runId }) || 0;
  const increment = useMutation(api.counter.incrementCounter);

  return (
    <div className="App">
      <h1>Collaborative Counter</h1>
      <p>Count is {count}</p>
      <button onClick={() => increment({ runId })}>Increment</button>
    </div>
  );
}

export default App;
